<?php
require __DIR__.'/../app/bootstrap.php'; require_login();
$where=[];$args=[];$q=trim((string)($_GET['q']??''));$type=$_GET['type']??'';$status=$_GET['status']??'';
if($q!==''){ $where[]='(a.asset_no LIKE ? OR a.hostname LIKE ? OR a.manufacturer LIKE ? OR a.model LIKE ? OR a.serial_no LIKE ? OR p.full_name LIKE ?)';for($i=0;$i<6;$i++)$args[]='%'.$q.'%'; }
if(in_array($type,['computer','printer','display','scanner'],true)){$where[]='a.asset_type=?';$args[]=$type;}if(in_array($status,['active','repair','retired','lost'],true)){$where[]='a.status=?';$args[]=$status;}
$sql='SELECT a.asset_no,a.asset_type,a.device_subtype,a.hostname,p.personnel_code,p.full_name personnel_name,a.location,a.department,a.manufacturer,a.model,a.serial_no,a.status,a.created_at,a.updated_at,a.source_file FROM assets a LEFT JOIN personnel p ON p.id=a.personnel_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY a.asset_no';$st=db()->prepare($sql);$st->execute($args);$rows=$st->fetchAll();
$map=['computer'=>'رایانه','printer'=>'چاپگر','display'=>'نمایشگر','scanner'=>'اسکنر'];$filename='ihw-assets-'.date('Ymd-His').'.csv';header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="'.$filename.'"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['شماره اموال','نوع دستگاه','زیرنوع','نام دستگاه','کد پرسنلی','مسئول','مکان','اداره/دانشکده','برند','مدل','سریال','وضعیت','تاریخ ثبت','آخرین بروزرسانی','فایل منبع']);foreach($rows as $r){fputcsv($out,[$r['asset_no'],$map[$r['asset_type']]??$r['asset_type'],$r['device_subtype'],$r['hostname'],$r['personnel_code'],$r['personnel_name'],$r['location'],$r['department'],$r['manufacturer'],$r['model'],$r['serial_no'],$r['status'],$r['created_at'],$r['updated_at'],$r['source_file']]);}fclose($out);audit('asset_report_export','asset',null,['count'=>count($rows)]);
